You’re right. The last change broke the preview path again.
Root cause: I pushed preview-v2 to fetch http://localhost:3000/... directly from the Vite app. That reintroduced the cross-origin/load failure path. The fix is to stop calling port 3000 directly from the browser and proxy /api through Vite instead.
Do these full file rewrites only.
1) Rewrite preview-v2/vite.config.ts
Bashcat > preview-v2/vite.config.ts << 'EOF'
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  server: {
    host: "0.0.0.0",
    port: 5173,
    proxy: {
      "/api": {
        target: "http://localhost:3000",
        changeOrigin: true,
      },
    },
  },
});
EOF
2) Rewrite preview-v2/src/main.tsx
Bashcat > preview-v2/src/main.tsx << 'EOF'
import React from "react";
import ReactDOM from "react-dom/client";

function normalize(code: string) {
  // remove imports
  code = code.replace(/^import .*$/gm, "");

  // convert export default function X -> function X
  code = code.replace(/export default function (\w+)/, "function $1");

  // very small normalized renderer for common UI wrappers
  const components = [
    "Card",
    "CardHeader",
    "CardContent",
    "CardTitle",
    "CardDescription",
  ];

  for (const name of components) {
    code = code.replace(new RegExp(`<${name}\\b`, "g"), "<div");
    code = code.replace(new RegExp(`</${name}>`, "g"), "</div>");
  }

  // fallback export
  code +=
    "\nreturn typeof Page !== 'undefined' ? Page : " +
    "(typeof CustomersPage !== 'undefined' ? CustomersPage : (() => React.createElement('div', null, 'No Preview')));";

  return code;
}

async function boot() {
  const container = document.getElementById("root");

  if (!container) {
    return;
  }

  const root = ReactDOM.createRoot(container);
  const params = new URLSearchParams(window.location.search);
  const projectId = params.get("projectId");

  if (!projectId) {
    root.render(<div style={{ padding: 20 }}>Missing projectId</div>);
    return;
  }

  try {
    const listRes = await fetch(`/api/dev/fs/list?projectId=${encodeURIComponent(projectId)}`);
    if (!listRes.ok) {
      throw new Error(`fs/list failed: ${listRes.status}`);
    }

    const listJson = await listRes.json();
    const files: string[] = Array.isArray(listJson?.files) ? listJson.files : [];

    const entry =
      files.find((f) => f === "app/page.tsx") ||
      files.find((f) => f.endsWith("/app/page.tsx")) ||
      files.find((f) => f.endsWith("page.tsx"));

    if (!entry) {
      root.render(<div style={{ padding: 20 }}>No page.tsx found</div>);
      return;
    }

    const readRes = await fetch(
      `/api/dev/fs/read?projectId=${encodeURIComponent(projectId)}&file=${encodeURIComponent(entry)}`
    );

    if (!readRes.ok) {
      throw new Error(`fs/read failed: ${readRes.status}`);
    }

    const fileJson = await readRes.json();
    const rawCode = typeof fileJson?.content === "string" ? fileJson.content : "";

    if (!rawCode) {
      root.render(<div style={{ padding: 20 }}>Empty entry file</div>);
      return;
    }

    const code = normalize(rawCode);
    const App = new Function("React", code)(React);

    root.render(
      <div style={{ padding: 20 }}>
        <App />
      </div>
    );
  } catch (err: any) {
    root.render(
      <pre style={{ color: "red", padding: 20, whiteSpace: "pre-wrap" }}>
        {String(err?.message || err)}
      </pre>
    );
  }
}

boot();
EOF
3) Restart only what matters
Bashnpm run dev:all
4) Test in this order
Open:


http://localhost:5173/?projectId=repo-test


http://localhost:3000/builder?projectId=repo-test


Expected:


repo-test should render again


imported repo should at least stop showing Load failed


